window.__finlexDocLoaded(10207,{"id":10207,"articles":[{"id":1000859,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Addresses extinguishment of liabilities (ASC 405-20), joint and several liability arrangements (ASC 405-40), and buyer disclosures for Supplier Finance Programs / reverse factoring (ASC 405-50, ASU 2022-04).","seq":0},{"id":1000860,"no":"ASC 405-20 / 405-50","heading":"Liability Derecognition & Supplier Finance Disclosures","text":"• Extinguishment (ASC 405-20-40-1): Derecognize a liability only when the debtor pays the creditor OR is legally released from being the primary obligor.\n• Supplier Finance Programs (ASC 405-50, ASU 2022-04): Buyers must disclose key program terms, confirmed obligations outstanding at period-end (and where presented on the balance sheet), and an annual rollforward of obligations.","seq":1},{"id":1000861,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Supplier finance disclosures are closely aligned with IAS 7 / IFRS 7 Supplier Finance Arrangements amendments (effective 2024).","seq":2},{"id":1000862,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
